PostgreSql.EnsureColumn:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public'
          AND table_name = 'article'
    ) THEN
        EXECUTE 'ALTER TABLE "article" ADD COLUMN IF NOT EXISTS "title" varchar(64) NULL';
    END IF;
END $$;

PostgreSql.RenameTable:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'article'
    )
    AND NOT EXISTS (
        SELECT 1 FROM information_schema.tables
        WHERE table_schema = 'public' AND table_name = 'article_archive'
    ) THEN
        EXECUTE 'ALTER TABLE "article" RENAME TO "article_archive"';
    END IF;
END $$;

PostgreSql.CreateIndex:
DO $$
BEGIN
    EXECUTE 'CREATE INDEX IF NOT EXISTS idx_article_title ON article (title);';
EXCEPTION
    WHEN undefined_table OR undefined_column THEN
        NULL;
END $$;
